graphql.query:
query Aventuriers($offset: Int, $limit: Int) {
  aventuriers(offset: $offset, limit: $limit) {
    id
    nom
    classe
    niveau
  }
}

query Registre($after: String, $first: Int) {
  aventuriersConnection(after: $after, first: $first) {
    edges {
      cursor
      node {
        id
        nom
        classe
      }
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

query Aventurier($id: BigInteger!) {
  aventurier(id: $id) {
    id
    nom
    classe
    niveau
    soldeOr
  }
}

